-- WARNING: Fresh install only. This script DROPS existing tables and data.
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS appointments; DROP TABLE IF EXISTS doctor_slots; DROP TABLE IF EXISTS admins; DROP TABLE IF EXISTS doctors; DROP TABLE IF EXISTS patients;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE patients(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,phone VARCHAR(30) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,age TINYINT UNSIGNED NOT NULL,gender VARCHAR(20) NOT NULL,address VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admins(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE doctors(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(60) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL,specialty VARCHAR(120) NOT NULL,is_active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE doctor_slots(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,doctor_id INT UNSIGNED NOT NULL,slot_date DATE NOT NULL,slot_time TIME NOT NULL,is_available TINYINT(1) NOT NULL DEFAULT 1,FOREIGN KEY(doctor_id) REFERENCES doctors(id) ON DELETE CASCADE,UNIQUE KEY unique_doctor_slot(doctor_id,slot_date,slot_time),INDEX idx_slot_lookup(doctor_id,slot_date,is_available)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE appointments(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,patient_id INT UNSIGNED NOT NULL,doctor_id INT UNSIGNED NOT NULL,slot_id INT UNSIGNED NOT NULL,appointment_date DATE NOT NULL,appointment_time TIME NOT NULL,problem_description TEXT NULL,status ENUM('PENDING','CONFIRMED','CANCELLED') NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(patient_id) REFERENCES patients(id) ON DELETE CASCADE,FOREIGN KEY(doctor_id) REFERENCES doctors(id) ON DELETE CASCADE,FOREIGN KEY(slot_id) REFERENCES doctor_slots(id) ON DELETE RESTRICT,UNIQUE KEY unique_appointment_slot(slot_id),INDEX idx_patient_appointments(patient_id),INDEX idx_doctor_today(doctor_id,appointment_date,status));
