INSERT INTO doctor_slots(doctor_id,slot_date,slot_time) SELECT d.id,DATE_ADD(CURDATE(),INTERVAL days.n DAY),times.slot_time FROM doctors d CROSS JOIN (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13) days CROSS JOIN (SELECT '09:00:00' slot_time UNION ALL SELECT '09:30:00' UNION ALL SELECT '10:00:00' UNION ALL SELECT '10:30:00' UNION ALL SELECT '11:00:00' UNION ALL SELECT '11:30:00' UNION ALL SELECT '14:00:00' UNION ALL SELECT '14:30:00' UNION ALL SELECT '15:00:00' UNION ALL SELECT '15:30:00') times;
